function verif1(){
    let mat=document.getElementById("mat").value;
    let nom=document.getElementById("nom").value;
    let prenom=document.getElementById("prenom").value;
    let f=document.getElementById("f").checked;
    let h=document.getElementById("h").checked;
    let email=document.getElementById("email").value;

    if (mat.length!=4 || !verif_alpha(mat.substr(0,2)) || !verif_num(mat.substr(2,4))){
        alert("matricule invalide");
        return false;
    }
    if (nom=="" || !verif_alpha(nom)){
        alert("nom invalide");
        return false;
    }
    if (prenom=="" || !verif_alpha(prenom)){
        alert("prenom invalide");
        return false;
    }
    if(!h && !f){
        alert("genre invalide");
        return false;
    }

    if(email.indexOf("@")==-1 || email.indexOf(".")==-1){
        alert("email invalide");
        return false;
    }
    let posat=email.indexOf("@");
    let posp=email.indexOf(".");
    if(!verif_alpha(email.substr(0,posat)) || !verif_alpha(email.substr(posat+1,posp)) || 2>(email.substr(posp+1,email.length+1)).length>3 || verif_alpha(email.substr(posp+1,email.length+1))){
        alert("email invalide");
        return false;
    }

}
function verif_alpha(ch){
    let i=0;
    ch=ch.ToUpperCase();
    while(i<ch.length && "A"<=ch[i]<="Z" ){
        i++;
    }
    return i==ch.length
}
function verif_num(ch){
    let i=0;
    while(i<ch.length && "0"<=ch[i]<="9" ){
        i++;
    }
    return i==ch.length
}

